import itertools
import random

def get_union_of_arcs(c_seq, s_seq):
    x = 0
    covered = []
    for c, s in zip(c_seq, s_seq):
        x_prev = x
        x = (x + s * c) % 1
        if s == 1:
            low, high = x_prev, x_prev + c
        else:
            low, high = x_prev - c, x_prev
        for k in range(-2, 3):
            L, H = low + k, high + k
            inter_L, inter_H = max(0, L), min(1, H)
            if inter_L < inter_H:
                covered.append((inter_L, inter_H))
    if not covered: return False
    covered.sort()
    merged = []
    curr_L, curr_H = covered[0]
    for next_L, next_H in covered[1:]:
        if next_L <= curr_H: curr_H = max(curr_H, next_H)
        else:
            merged.append((curr_L, curr_H))
            curr_L, curr_H = next_L, next_H
    merged.append((curr_L, curr_H))
    return len(merged) == 1 and merged[0][0] <= 0 and merged[0][1] >= 1

def check_sequence(c_seq):
    for s_seq in itertools.product([-1, 1], repeat=len(c_seq)):
        if not get_union_of_arcs(c_seq, s_seq):
            return False
    return True

# Search for a sequence with c_i < 0.5 that forces coverage
for _ in range(100000):
    c_seq = [random.uniform(0.1, 0.49) for _ in range(6)]
    if check_sequence(c_seq):
        print(f"Found sequence: {c_seq}")
        break
else:
    print("No sequence found with c_i < 0.5 in 100,000 trials")

