def can_avoid_point(c_seq):
    # We want to find if there exists s_seq such that the union of arcs is not the whole circle.
    # We can use DFS to find such s_seq.

    def get_current_covered(s_prefix):
        x = 0
        covered = []
        for i in range(len(s_prefix)):
            c = c_seq[i]
            s = s_prefix[i]
            x_prev = x
            x = (x + s * c) % 1
            if s == 1:
                low, high = x_prev, x_prev + c
            else:
                low, high = x_prev - c, x_prev
            for k in range(-2, 3):
                L, H = low + k, high + k
                inter_L, inter_H = max(0, L), min(1, H)
                if inter_L < inter_H:
                    covered.append((inter_L, inter_H))

        if not covered: return []
        covered.sort()
        merged = []
        curr_L, curr_H = covered[0]
        for next_L, next_H in covered[1:]:
            if next_L <= curr_H: curr_H = max(curr_H, next_H)
            else:
                merged.append((curr_L, curr_H))
                curr_L, curr_H = next_L, next_H
        merged.append((curr_L, curr_H))
        return merged

    def is_full(merged):
        return len(merged) == 1 and merged[0][0] <= 0 and merged[0][1] >= 1

    def dfs(s_prefix):
        merged = get_current_covered(s_prefix)
        if is_full(merged):
            return False # This path covers the circle
        if len(s_prefix) == len(c_seq):
            return True # Found a path that doesn't cover the circle

        # Try both s = 1 and s = -1
        if dfs(s_prefix + [1]): return True
        if dfs(s_prefix + [-1]): return True
        return False

    return dfs([])

